import re

_PART = re.compile(r"(\d+)([hms])")
_UNITS = {"h": 3600, "m": 60, "s": 1}


def parse_duration(s: str) -> int:
    """'1h30m' -> 5400. Units must come in h, m, s order, each at most once."""
    if not isinstance(s, str) or not s:
        raise ValueError("empty duration")
    pos, total, seen = 0, 0, ""
    for m in _PART.finditer(s):
        if m.start() != pos:
            raise ValueError(f"bad duration: {s!r}")
        unit = m.group(2)
        if seen and "hms".index(unit) <= "hms".index(seen[-1]):
            raise ValueError(f"units out of order in {s!r}")
        seen += unit
        total += int(m.group(1)) * _UNITS[unit]
        pos = m.end()
    if pos != len(s) or not seen:
        raise ValueError(f"bad duration: {s!r}")
    return total
```

