```python
import re


def parse_duration(s):
    m = re.fullmatch(r"(?:(\d+)h)?(?:(\d+)s)?", s)
    if not m or not s:
        raise ValueError(s)
    h, sec = m.groups()
    return int(h or 0) * 3600 + int(sec or 0)
```

